public static Plane DefaultComputeChildPlane(
    Plane parentPlane,
    Point parentPoint,
    Vector parentDirection,
    Point childPoint,
    Vector childDirection,
    double gap,
    double shift,
    double rise,
    double rotation,
    double turn,
    double tilt)
{
